mapper.select:
SELECT i.hq_inbound_id AS inboundId, s.supplier_name AS supplierName, mg.group_name AS categoryName, m.material_name AS itemName, m.unit AS unit, i.qty AS quantity, m.material_price AS unitPrice, (i.qty * m.material_price) AS totalPrice, i.expiry_date AS expiryDate, DATE_FORMAT(i.received_at, '%Y-%m-%d %H:%i') AS receivedAt FROM hq_inbound i JOIN supplier s ON i.supplier_id = s.supplier_id JOIN material m ON i.material_code = m.material_code JOIN material_group mg ON m.material_group_id = mg.material_group_id
AND s.supplier_name = #{supplierName}
AND mg.group_name = #{categoryName}
AND m.material_name = #{itemName}
AND DATE(i.received_at) >= #{startDate}
AND DATE(i.received_at) <= #{endDate}
ORDER BY i.received_at DESC

mapper.insert:
INSERT INTO hq_inbound (
    supplier_id, received_at, material_code, qty, expiry_date
)

SELECT
    s.supplier_id,
    NOW(),
    m.material_code,
    #{quantity},
    #{expiryDate}
FROM supplier s
JOIN material m ON m.material_name = #{itemName}
WHERE s.supplier_name = #{supplier}

mapper.select:
SELECT ws.id AS id, ws.stock_no AS stockNo, ws.material_code AS itemCode, mg.group_name AS category, m.material_name AS itemName, ws.qty AS quantity, m.unit AS unit, DATE_FORMAT(ws.received_at, '%Y-%m-%d') AS receivedDate, DATE_FORMAT(ws.expiry_date, '%Y-%m-%d') AS expiryDate, DATEDIFF(ws.expiry_date, CURDATE()) AS daysLeft, m.material_price AS unitPrice, (ws.qty * m.material_price) AS totalValue, CASE WHEN DATEDIFF(ws.expiry_date, CURDATE()) <= 1 THEN 'urgent' WHEN DATEDIFF(ws.expiry_date, CURDATE()) <= 3 THEN 'warning' ELSE 'normal' END AS status FROM warehouse_stock ws JOIN material m ON ws.material_code = m.material_code JOIN material_group mg ON m.material_group_id = mg.material_group_id
ws.status = 'AVAILABLE' AND ws.expiry_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY)
AND mg.group_name = #{category}
AND m.material_name = #{itemName}
AND ( ws.stock_no LIKE CONCAT('%', #{search}, '%') OR mg.group_name LIKE CONCAT('%', #{search}, '%') OR m.material_name LIKE CONCAT('%', #{search}, '%') )
ORDER BY ws.expiry_date ASC

mapper.update:
UPDATE warehouse_stock
SET status = #{status}
WHERE stock_no = #{stockNo}
